const GUESTS = {"hourmath.fixoraa.tech": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>HourMath \u2014 Time Duration Calculator | Add &amp; Subtract Hours for Payroll</title>\n<meta name=\"description\" content=\"HourMath is a free time duration calculator: add and subtract many HH:MM entries, get decimal-hours totals for payroll, apply rounding, and copy clean timesheet rows instantly.\">\n<script src=\"https://cdn.tailwindcss.com\"></script>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link href=\"https://fonts.googleapis.com/css2?family=Fraunces:wght@600;700;900&family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  body{font-family:'Inter',system-ui,sans-serif;background:#FFF8EC;color:#431407}\n  .font-display{font-family:'Fraunces',serif}\n  .font-mono2{font-family:'JetBrains Mono',monospace}\n  .pad-btn{transition:all .15s}\n  .pad-btn:hover{transform:translateY(-1px);box-shadow:0 6px 16px rgba(154,52,18,.18)}\n  .pad-btn:active{transform:translateY(0)}\n  input:focus,select:focus,textarea:focus{outline:2px solid #EA580C;outline-offset:1px}\n</style>\n<script type=\"application/ld+json\">\n{\"@context\":\"https://schema.org\",\"@type\":\"FAQPage\",\"mainEntity\":[{\"@type\":\"Question\",\"name\":\"How do I add multiple HH:MM durations together?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Type each duration as hours and minutes, such as 7:30, choose the plus sign for entries you want to add, and HourMath totals them instantly. You can add as many rows as you need, mix formats like 1.5 hours or 90 minutes, and the running total updates in HH:MM, decimal hours, and total minutes at the same time.\"}},{\"@type\":\"Question\",\"name\":\"How do I subtract time, breaks, or unpaid leave from a total?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Add the break or deduction as its own row and switch its sign to minus. HourMath subtracts that row from the running total, which is ideal for unpaid lunch breaks, early departures, or corrections. The total can go negative if deductions exceed additions, so you can spot errors before submitting a timesheet.\"}},{\"@type\":\"Question\",\"name\":\"What is decimal time and why does payroll need it?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Decimal time expresses a duration as a single number of hours, so 7 hours 30 minutes becomes 7.50 hours. Payroll systems multiply decimal hours by an hourly rate to calculate pay, which is why HourMath always shows the decimal total next to the HH:MM total and lets you copy it directly into payroll or invoicing software.\"}},{\"@type\":\"Question\",\"name\":\"How does payroll rounding work in HourMath?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Many employers round clocked time to the nearest 6, 10, or 15 minutes. Choose a rounding increment and a direction \u2014 nearest, up, or down \u2014 in the payroll panel and HourMath shows both the exact total and the rounded total with its decimal equivalent, so you can compare them before you submit.\"}},{\"@type\":\"Question\",\"name\":\"Can I calculate the duration between a start and end time?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"Yes. Use the shift calculator inside HourMath: enter a start time and an end time in 24-hour format, tick the overnight option if the shift crosses midnight, subtract any break minutes, and add the net duration straight into your list of entries with one click.\"}},{\"@type\":\"Question\",\"name\":\"How do I copy my hours into a timesheet or spreadsheet?\",\"acceptedAnswer\":{\"@type\":\"Answer\",\"text\":\"HourMath builds tab-separated timesheet rows with a label, sign, HH:MM value, and decimal value for every entry, plus a total row. Press Copy Timesheet and paste directly into Excel, Google Sheets, or your payroll system \u2014 each value lands in its own column. You can also download the rows as a text or CSV file.\"}}]}\n</script>\n</head>\n<body id=\"top\">\n<header class=\"sticky top-0 z-50 bg-[#FFF8EC]/95 backdrop-blur border-b-2 border-[#9A3412]\">\n  <div class=\"max-w-6xl mx-auto px-4 sm:px-6 h-16 flex items-center justify-between\">\n    <a href=\"#top\" class=\"flex items-center gap-2.5\">\n      <span class=\"w-10 h-10 rounded-full bg-[#9A3412] text-[#FFF8EC] grid place-items-center text-xl\" aria-hidden=\"true\">\u25f7</span>\n      <span class=\"font-display font-black text-2xl tracking-tight\">Hour<span class=\"text-[#C2410C]\">Math</span></span>\n    </a>\n    <nav class=\"flex items-center gap-2 sm:gap-4 text-sm font-semibold\">\n      <a href=\"#top\" class=\"px-3 py-2 rounded-full hover:bg-[#FED7AA]\">Home</a>\n      <a href=\"https://fixoraa.tech\" class=\"px-3 py-2 rounded-full bg-[#431407] text-white hover:bg-[#9A3412]\">More Tools</a>\n    </nav>\n  </div>\n</header>\n\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pt-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <div class=\"origin-top scale-[0.44] sm:scale-100 shrink-0\">\n        <script>\n          atOptions = { 'key' : '4e68ac77881c17fe128a46565d9a4e8c', 'format' : 'iframe', 'height' : 90, 'width' : 728, 'params' : {} };\n        </script>\n        <script src=\"https://www.highrevenueformat.com/4e68ac77881c17fe128a46565d9a4e8c/invoke.js\"></script>\n      </div>\n    </div>\n  </div>\n</div>\n\n<main class=\"max-w-6xl mx-auto px-4 sm:px-6 py-8\">\n  <div class=\"text-center max-w-2xl mx-auto\">\n    <span class=\"inline-block bg-[#9A3412] text-white text-xs font-bold tracking-widest uppercase px-3 py-1.5 rounded-full\">\u2726 Unlimited Free Usage</span>\n    <h1 class=\"font-display font-black text-4xl sm:text-5xl leading-tight mt-4\">Time Duration Calculator</h1>\n    <p class=\"mt-3 text-[#7C2D12] text-base sm:text-lg\">Add and subtract a whole week of HH:MM entries on one calculator pad. Get the payroll-ready decimal total, round it fairly, and copy tidy timesheet rows \u2014 no spreadsheet formulas required.</p>\n  </div>\n\n  <!-- CALCULATOR PAD -->\n  <section class=\"mt-8 bg-[#431407] rounded-[2rem] p-3 sm:p-5 shadow-2xl shadow-orange-900/30\" aria-label=\"Time duration calculator\">\n    <div class=\"bg-[#FFFBEB] rounded-[1.6rem] overflow-hidden\">\n      <!-- Display -->\n      <div class=\"bg-[#292524] text-[#FFFBEB] px-5 sm:px-8 py-6\">\n        <div class=\"flex flex-wrap items-end justify-between gap-4\">\n          <div>\n            <p class=\"text-[11px] tracking-[0.2em] uppercase text-orange-300 font-bold\">Running total</p>\n            <p id=\"displayTotal\" class=\"font-mono2 font-bold text-5xl sm:text-6xl mt-1\">0:00</p>\n            <p id=\"displaySub\" class=\"text-orange-200 text-sm mt-1\">0.00 decimal hours \u00b7 0 minutes</p>\n          </div>\n          <div class=\"text-right\">\n            <p class=\"text-[11px] tracking-widest uppercase text-orange-300 font-bold\">Breakdown</p>\n            <p id=\"displayBreak\" class=\"font-semibold mt-1\">0 days \u00b7 0 hrs \u00b7 0 min</p>\n            <p id=\"displayAvg\" class=\"text-orange-200 text-sm\">Average per entry: \u2014</p>\n          </div>\n        </div>\n        <p id=\"calcMsg\" class=\"mt-3 text-sm bg-white/10 rounded-xl px-3 py-2\" role=\"status\">Add your first duration below \u2014 try 7:30, 1.5, or 45m. All three formats work.</p>\n      </div>\n\n      <div class=\"grid lg:grid-cols-5 gap-0\">\n        <!-- Entries -->\n        <div class=\"lg:col-span-3 p-5 sm:p-7\">\n          <div class=\"flex items-center justify-between\">\n            <h2 class=\"font-display font-bold text-xl\">Your entries <span class=\"text-sm font-sans font-semibold text-[#9A3412]\" id=\"entryCount\"></span></h2>\n            <button id=\"clearBtn\" class=\"text-sm font-bold text-[#9A3412] underline underline-offset-2\">Clear all</button>\n          </div>\n          <div id=\"entriesList\" class=\"mt-4 space-y-2.5\"></div>\n          <p id=\"emptyState\" class=\"mt-4 border-2 border-dashed border-[#FDBA74] rounded-2xl p-4 text-center text-[#7C2D12] text-sm\">No entries yet. Press <strong>+ Add entry</strong> or tap a quick-add chip on the pad.</p>\n\n          <div class=\"mt-5 flex flex-wrap gap-2\">\n            <button id=\"addEntryBtn\" class=\"bg-[#C2410C] hover:bg-[#9A3412] text-white font-bold px-5 py-3 rounded-full\">+ Add entry</button>\n            <button data-preset=\"workday\" class=\"pad-btn bg-white border-2 border-[#431407] font-bold px-4 py-3 rounded-full text-sm\">+ Full workday 8:00</button>\n            <button data-preset=\"week\" class=\"pad-btn bg-white border-2 border-[#431407] font-bold px-4 py-3 rounded-full text-sm\">Load sample week</button>\n          </div>\n\n          <div class=\"mt-6 bg-[#FFF7ED] border border-[#FDBA74] rounded-2xl p-4\">\n            <h3 class=\"font-bold\">\u23f1 Shift calculator \u2014 start to end</h3>\n            <p class=\"text-sm text-[#7C2D12] mt-1\">Work out one shift, minus its break, then drop the net duration into the list above.</p>\n            <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 mt-3\">\n              <label class=\"text-xs font-bold\">Start <input id=\"shiftStart\" type=\"time\" value=\"09:00\" class=\"mt-1 w-full rounded-xl border border-[#D6D3D1] px-2 py-2.5 bg-white font-mono2\"></label>\n              <label class=\"text-xs font-bold\">End <input id=\"shiftEnd\" type=\"time\" value=\"17:30\" class=\"mt-1 w-full rounded-xl border border-[#D6D3D1] px-2 py-2.5 bg-white font-mono2\"></label>\n              <label class=\"text-xs font-bold\">Break (min) <input id=\"shiftBreak\" type=\"number\" min=\"0\" value=\"30\" class=\"mt-1 w-full rounded-xl border border-[#D6D3D1] px-2 py-2.5 bg-white font-mono2\"></label>\n              <label class=\"text-xs font-bold flex items-end gap-2 pb-1\"><input id=\"shiftOvernight\" type=\"checkbox\" class=\"w-5 h-5 accent-[#C2410C]\"> Overnight</label>\n            </div>\n            <div class=\"flex flex-wrap items-center gap-3 mt-3\">\n              <button id=\"shiftCalcBtn\" class=\"bg-[#431407] text-white font-bold px-4 py-2.5 rounded-full text-sm\">Calculate shift</button>\n              <span id=\"shiftResult\" class=\"font-mono2 font-bold text-[#9A3412]\">\u2014</span>\n              <button id=\"shiftAddBtn\" class=\"hidden bg-[#C2410C] text-white font-bold px-4 py-2.5 rounded-full text-sm\">Add shift to entries \u2191</button>\n            </div>\n          </div>\n        </div>\n\n        <!-- Pad + payroll -->\n        <div class=\"lg:col-span-2 bg-[#FFEDD5] p-5 sm:p-7 border-t lg:border-t-0 lg:border-l border-[#FDBA74]\">\n          <h3 class=\"font-display font-bold text-lg\">Quick-add pad</h3>\n          <div class=\"grid grid-cols-3 gap-2 mt-3\">\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"15\">+ 0:15</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"30\">+ 0:30</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"45\">+ 0:45</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"60\">+ 1:00</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"90\">+ 1:30</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"120\">+ 2:00</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"240\">+ 4:00</button>\n            <button class=\"pad-btn quick-add bg-white rounded-2xl py-3.5 font-mono2 font-bold border border-[#FDBA74]\" data-mins=\"480\">+ 8:00</button>\n            <button class=\"pad-btn quick-sub bg-[#431407] text-white rounded-2xl py-3.5 font-mono2 font-bold\" data-mins=\"30\">\u2212 0:30 break</button>\n          </div>\n          <p class=\"text-xs text-[#7C2D12] mt-2\">Each tap adds a labelled row you can edit or delete. Nothing is final until you copy it.</p>\n\n          <h3 class=\"font-display font-bold text-lg mt-7\">Payroll panel</h3>\n          <label class=\"block text-xs font-bold mt-3\">Round total to nearest\n            <select id=\"roundInc\" class=\"mt-1 w-full rounded-xl border border-[#D6D3D1] px-3 py-2.5 bg-white\">\n              <option value=\"0\">No rounding (exact)</option>\n              <option value=\"6\">6 minutes (0.10 hr)</option>\n              <option value=\"10\">10 minutes</option>\n              <option value=\"15\" selected>15 minutes (quarter hour)</option>\n              <option value=\"30\">30 minutes (half hour)</option>\n            </select>\n          </label>\n          <label class=\"block text-xs font-bold mt-3\">Rounding direction\n            <select id=\"roundMode\" class=\"mt-1 w-full rounded-xl border border-[#D6D3D1] px-3 py-2.5 bg-white\">\n              <option value=\"nearest\" selected>Nearest</option><option value=\"up\">Always up</option><option value=\"down\">Always down</option>\n            </select>\n          </label>\n          <label class=\"block text-xs font-bold mt-3\">Hourly rate (optional, for billable total)\n            <input id=\"hourlyRate\" type=\"number\" min=\"0\" step=\"0.01\" placeholder=\"e.g. 25\" class=\"mt-1 w-full rounded-xl border border-[#D6D3D1] px-3 py-2.5 bg-white font-mono2\">\n          </label>\n          <div class=\"bg-white rounded-2xl border border-[#FDBA74] p-4 mt-4 space-y-1.5 text-sm\">\n            <p class=\"flex justify-between\"><span>Rounded total</span><strong id=\"roundedOut\" class=\"font-mono2\">0:00 \u00b7 0.00 hrs</strong></p>\n            <p class=\"flex justify-between\"><span>Billable (rounded \u00d7 rate)</span><strong id=\"billableOut\" class=\"font-mono2\">\u2014</strong></p>\n          </div>\n\n          <h3 class=\"font-display font-bold text-lg mt-7\">Timesheet rows</h3>\n          <textarea id=\"timesheetOut\" rows=\"6\" readonly class=\"mt-2 w-full rounded-2xl border border-[#D6D3D1] bg-white p-3 font-mono2 text-xs leading-relaxed\" placeholder=\"Your copyable rows will appear here\u2026\"></textarea>\n          <div class=\"flex flex-wrap gap-2 mt-2\">\n            <button id=\"copyBtn\" class=\"bg-[#C2410C] hover:bg-[#9A3412] text-white font-bold px-4 py-2.5 rounded-full text-sm\">Copy timesheet</button>\n            <button id=\"csvBtn\" class=\"bg-white border-2 border-[#431407] font-bold px-4 py-2.5 rounded-full text-sm\">Download .csv</button>\n          </div>\n          <p id=\"copyMsg\" class=\"text-sm font-semibold text-[#9A3412] mt-2\" role=\"status\"></p>\n        </div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"grid sm:grid-cols-3 gap-4 mt-6 text-sm\">\n    <div class=\"bg-white rounded-2xl border border-[#FDBA74] p-5\"><h3 class=\"font-bold text-base\">\ud83e\uddee Many entries, one total</h3><p class=\"mt-1 text-[#7C2D12]\">Unlike two-value calculators, HourMath keeps a full tape of rows. Add a whole week, subtract breaks and corrections, and watch every format update together.</p></div>\n    <div class=\"bg-white rounded-2xl border border-[#FDBA74] p-5\"><h3 class=\"font-bold text-base\">\ud83d\udcb7 Decimal hours for payroll</h3><p class=\"mt-1 text-[#7C2D12]\">Payroll multiplies hours by a rate, so 7:30 must become 7.50. HourMath shows both side by side, with 6-, 15-, and 30-minute rounding built in.</p></div>\n    <div class=\"bg-white rounded-2xl border border-[#FDBA74] p-5\"><h3 class=\"font-bold text-base\">\ud83d\udccb Copyable timesheet rows</h3><p class=\"mt-1 text-[#7C2D12]\">One click copies tab-separated rows that paste neatly into Excel, Google Sheets, or payroll software \u2014 each label, duration, and decimal in its own column.</p></div>\n  </section>\n\n  <!-- SEO ARTICLE -->\n  <article id=\"seo-article\" class=\"mt-12 bg-white rounded-[2rem] border border-[#FDBA74] p-6 sm:p-10 prose-like\">\n    <h2 class=\"font-display font-black text-3xl\">Time Duration Calculator: How to Add, Subtract, and Convert Hours Without the Headache</h2>\n    <p class=\"mt-4 leading-relaxed\">Time refuses to behave like ordinary numbers. An hour holds sixty minutes, not one hundred, so the moment you try to add 7:45 and 6:30 in your head \u2014 or worse, in a spreadsheet cell formatted as a plain number \u2014 the arithmetic starts to drift. Is the answer 13:75, 14:15, or 14.25? All three look plausible, only one is right, and payroll mistakes hide exactly in that gap. A dedicated time duration calculator exists to close the gap. HourMath lets you add and subtract as many HH:MM entries as you need, converts the total into decimal hours for payroll, applies fair rounding rules, and hands you clean, copyable timesheet rows at the end. This guide explains how duration arithmetic really works, why decimal time matters so much for pay, and how to check any total \u2014 whether it covers a single shift, a freelance project, or an entire working week.</p>\n\n    <h3 class=\"font-display font-bold text-2xl mt-8\">Why adding time is harder than adding numbers</h3>\n    <p class=\"mt-3 leading-relaxed\">Everyday arithmetic is decimal: ten units make the next column. Time is sexagesimal, a system inherited from Babylonian astronomy, in which sixty minutes make an hour and sixty seconds make a minute. That single difference explains almost every timesheet error ever made. When you add 50 minutes to 40 minutes you do not get 90 minutes in the final answer; you get one hour and thirty minutes, because sixty of those minutes must be carried into the hours column. People who add times in a hurry routinely forget the carry, or carry one hundred instead of sixty, or average the two mistakes and hope nobody checks. A duration calculator never forgets, because it converts every entry into a single unit \u2014 total minutes \u2014 before doing any arithmetic at all. Adding in minutes is ordinary decimal addition. Only at the end does the calculator convert back, dividing by sixty for the hours and keeping the remainder as minutes. That convert-add-convert method is the whole secret, and it is why a tool like HourMath stays accurate across dozens of entries where mental maths quietly falls apart by five or ten minutes at a time.</p>\n    <p class=\"mt-3 leading-relaxed\">Subtraction brings its own trap: borrowing. Taking a 45-minute unpaid break away from a 7-hour-20-minute shift means borrowing an hour as sixty minutes before the subtraction can even start. Do that five times across a week of shifts, alongside overtime, early finishes, and one correction for a forgotten clock-in, and a paper timesheet becomes a small minefield. In HourMath each deduction is simply its own row with a minus sign, so breaks, unpaid leave, and corrections sit visibly on the tape. You can see exactly what was taken away, delete a deduction you entered twice, and trust that the running total reflects the entries in front of you rather than a chain of invisible borrowing steps.</p>\n\n    <h3 class=\"font-display font-bold text-2xl mt-8\">Decimal hours: the language payroll actually speaks</h3>\n    <p class=\"mt-3 leading-relaxed\">If durations are naturally written as hours and minutes, why does every payroll department ask for decimal hours? Because money is decimal. Pay is an hourly rate multiplied by hours worked, and multiplication needs a single number. Seven hours and thirty minutes cannot be multiplied by a rate until it becomes 7.50 hours; seven hours and forty-five minutes becomes 7.75; seven hours and twenty minutes becomes 7.33 recurring. The conversion is simple in principle \u2014 divide the minutes by sixty and add the result to the hours \u2014 but it is a notorious source of underpayment when done by eye. The classic error is reading 7:30 as 7.30 hours, which quietly steals twelve minutes of pay from every single shift. Over a month of shifts that theft-by-rounding adds up to hours. HourMath displays the HH:MM total and the decimal total side by side at all times, so the two can never drift apart unnoticed, and the timesheet rows it copies carry both formats into your spreadsheet or payroll portal.</p>\n    <p class=\"mt-3 leading-relaxed\">Decimal conversion also unlocks everything else money-related. Multiply decimal hours by an hourly rate and you have gross pay for the period, or a freelance invoice line, or the labour cost of a project. Divide a project fee by its decimal hours and you discover your true effective rate \u2014 often a sobering number for freelancers who estimated a job at ten hours and logged fourteen. HourMath includes an optional rate field for exactly this purpose: enter a rate and the billable panel multiplies your rounded decimal total by it, giving you an instant invoice figure without opening a spreadsheet. Teachers use the same trick in reverse for grading time, coaches for session billing, and landlords for hourly room hire. Anywhere a duration meets a price, decimal hours are the bridge.</p>\n\n    <h3 class=\"font-display font-bold text-2xl mt-8\">Rounding rules: quarters, tenths, and fairness</h3>\n    <p class=\"mt-3 leading-relaxed\">Very few employers pay to the exact minute. Most round recorded time to a standard increment, and knowing which increment your workplace uses \u2014 and in which direction it rounds \u2014 is essential to checking your own pay. The most common scheme rounds to the nearest quarter hour, fifteen minutes, which is why clock-in systems love times ending in :00, :15, :30, and :45. Another widespread scheme rounds to the nearest tenth of an hour, six minutes, because a tenth converts to decimals so cleanly: 0.1 hours is exactly six minutes. Some workplaces round to the nearest five minutes, some to the half hour, and a few round all starts down and all finishes up, or the reverse, in the employer's favour. Labour rules in many jurisdictions require rounding to be neutral on average \u2014 it must sometimes favour the worker and sometimes the employer \u2014 but you can only verify neutrality if you keep your exact, unrounded totals. That is precisely the habit HourMath encourages: it always preserves the exact total, then shows the rounded total beside it, so the difference between what you worked and what you will be paid for is never hidden. If the rounded figure is consistently lower across a month, you have clear, dated evidence rather than a vague feeling.</p>\n    <p class=\"mt-3 leading-relaxed\">Rounding also matters far beyond payroll. Lawyers and consultants who bill in six-minute units are literally rounding every task to a tenth of an hour. Fitness coaches round session lengths, equipment hire rounds to the half day, and car parks round to the hour. In each case the method is identical: choose an increment, choose a direction \u2014 nearest, always up, or always down \u2014 and apply it consistently. HourMath's payroll panel offers increments of 6, 10, 15, and 30 minutes in all three directions, so you can model your employer's exact scheme, a client's billing scheme, or a hire company's scheme with the same tool.</p>\n\n    <h3 class=\"font-display font-bold text-2xl mt-8\">Calculating a single shift: starts, ends, breaks, and midnight</h3>\n    <p class=\"mt-3 leading-relaxed\">Half of all duration questions are really shift questions: I started at 09:00, finished at 17:30, and took thirty minutes for lunch \u2014 how long did I actually work? The method is to convert both clock times into minutes since midnight, subtract the start from the end, then subtract the break. Nine in the morning becomes 540 minutes, half past five in the evening becomes 1,050 minutes, and the difference is 510 minutes \u2014 eight and a half hours \u2014 from which a thirty-minute break leaves exactly eight working hours. Night shifts break the naive version of this method, because a shift that runs from 22:00 to 06:00 produces a negative difference. The fix is to add a full day, 1,440 minutes, whenever the end falls before the start, which is what the overnight option in HourMath's shift calculator does for you. Healthcare workers, security staff, bakers, and anyone on rotating rosters live on overnight arithmetic, and it is the calculation most likely to be wrong on a paper rota. Enter the start, the end, the break, and tick overnight; the net shift drops into your entry list as one labelled row, ready to join the rest of the week.</p>\n    <p class=\"mt-3 leading-relaxed\">Breaks deserve special attention because they are not all equal. Paid rest breaks stay inside the working duration; unpaid meal breaks come out. Some contracts deduct a standard break automatically whether you took it or not, which is a frequent source of disputes when a busy shift swallows lunch entirely. Recording the gross shift and the actual break as separate rows \u2014 one addition, one subtraction \u2014 keeps the record honest and adjustable. If a manager agrees the missed lunch should be paid, you delete one minus row and the total corrects itself. That transparency is the real advantage of a tape-style calculator over a single-answer box: the reasoning stays visible, editable, and copyable long after the arithmetic is done.</p>\n\n    <h3 class=\"font-display font-bold text-2xl mt-8\">Adding up a week, a project, or a semester</h3>\n    <p class=\"mt-3 leading-relaxed\">The other half of duration questions are accumulation questions. How many hours did I work this week? How long did that project really take? How many practice hours has a music student logged this term, how many study hours before an exam, how many hours has a machine run since its last service? Accumulation is where small errors compound: five shifts, each mis-added by just six minutes, produce a weekly total that is half an hour wrong \u2014 enough to matter for overtime thresholds. Overtime is usually calculated on the accumulated total, not on individual days, so the weekly sum determines whether hours beyond forty are paid at time-and-a-half. A half-hour error can therefore be paid at entirely the wrong rate. HourMath's sample week button demonstrates the pattern: five daily rows, one deduction for a long lunch, and an instant total with its decimal and average-per-entry figures. The average is quietly useful \u2014 it reveals whether a project estimate was realistic, whether study sessions are shrinking, and whether a team's logged hours match the hours a task was quoted for.</p>\n    <p class=\"mt-3 leading-relaxed\">For freelancers and agencies, accumulated durations become invoices. The copyable timesheet is built for that moment: every row carries its label, its sign, its HH:MM value, and its decimal value, separated by tabs so a paste into Excel or Google Sheets lands each piece in its own column. Add a total row and the sheet can be checked, sorted, and summed by the client as easily as by you. Students tracking revision, athletes tracking training load, volunteers tracking service hours for an application, and parents dividing screen time all use the same pattern \u2014 many small durations, honestly added, presented in a format someone else can verify. Duration arithmetic is rarely glamorous, but it underpins pay, invoices, qualifications, and rest, which makes getting it right a genuinely valuable habit.</p>\n\n    <h3 class=\"font-display font-bold text-2xl mt-8\">Formats that trip people up \u2014 and how HourMath handles them</h3>\n    <p class=\"mt-3 leading-relaxed\">Durations arrive in messy formats. A rota says 7.5, a time clock says 7:30, a colleague texts \u201cabout 45 mins\u201d, and a stopwatch says 7:30:00. These are four writings of related ideas and a good calculator should accept them all. HourMath accepts HH:MM, HH:MM:SS with seconds, decimal hours such as 1.5, and unit forms such as 2h 30m or 45m, converting each into minutes internally before adding. The one format to treat with suspicion is the ambiguous plain number typed into a spreadsheet, where 7.30 might mean seven hours thirty or seven point three hours depending on who typed it \u2014 a difference of twelve minutes. Being explicit about format is a professional habit: write durations with a colon for clock-style time, reserve decimal points for decimal hours, and label which is which on anything you share. When HourMath copies your timesheet it follows its own advice, placing the HH:MM value and the decimal value in separate, clearly ordered columns so no reader has to guess.</p>\n    <p class=\"mt-3 leading-relaxed\">A final trap is the 24-hour boundary. A duration is not a time of day, so totals above 24 hours are perfectly normal: a week of work is forty hours, a project is a hundred and twenty, a machine's runtime is measured in thousands. Calculators that borrow clock logic sometimes wrap totals past midnight back to zero, destroying long accumulations. HourMath never wraps: 25:00 means twenty-five hours, displayed plainly, with the day breakdown shown separately when it helps \u2014 one day plus one hour \u2014 without ever changing the underlying total. Whether you are adding two short tasks or two hundred shifts, the method stays the same, the tape stays visible, and the total stays true. That reliability, more than any single feature, is what a time duration calculator owes you.</p>\n\n    <h2 class=\"font-display font-black text-3xl mt-10\">Frequently Asked Questions</h2>\n    <div class=\"mt-5 space-y-4\">\n      <div class=\"border border-[#FDBA74] rounded-2xl p-5\"><h3 class=\"font-bold\">How do I add multiple HH:MM durations together?</h3><p class=\"mt-2 leading-relaxed text-[#7C2D12]\">Type each duration as hours and minutes, such as 7:30, choose the plus sign for entries you want to add, and HourMath totals them instantly. You can add as many rows as you need, mix formats like 1.5 hours or 90 minutes, and the running total updates in HH:MM, decimal hours, and total minutes at the same time.</p></div>\n      <div class=\"border border-[#FDBA74] rounded-2xl p-5\"><h3 class=\"font-bold\">How do I subtract time, breaks, or unpaid leave from a total?</h3><p class=\"mt-2 leading-relaxed text-[#7C2D12]\">Add the break or deduction as its own row and switch its sign to minus. HourMath subtracts that row from the running total, which is ideal for unpaid lunch breaks, early departures, or corrections. The total can go negative if deductions exceed additions, so you can spot errors before submitting a timesheet.</p></div>\n      <div class=\"border border-[#FDBA74] rounded-2xl p-5\"><h3 class=\"font-bold\">What is decimal time and why does payroll need it?</h3><p class=\"mt-2 leading-relaxed text-[#7C2D12]\">Decimal time expresses a duration as a single number of hours, so 7 hours 30 minutes becomes 7.50 hours. Payroll systems multiply decimal hours by an hourly rate to calculate pay, which is why HourMath always shows the decimal total next to the HH:MM total and lets you copy it directly into payroll or invoicing software.</p></div>\n      <div class=\"border border-[#FDBA74] rounded-2xl p-5\"><h3 class=\"font-bold\">How does payroll rounding work in HourMath?</h3><p class=\"mt-2 leading-relaxed text-[#7C2D12]\">Many employers round clocked time to the nearest 6, 10, or 15 minutes. Choose a rounding increment and a direction \u2014 nearest, up, or down \u2014 in the payroll panel and HourMath shows both the exact total and the rounded total with its decimal equivalent, so you can compare them before you submit.</p></div>\n      <div class=\"border border-[#FDBA74] rounded-2xl p-5\"><h3 class=\"font-bold\">Can I calculate the duration between a start and end time?</h3><p class=\"mt-2 leading-relaxed text-[#7C2D12]\">Yes. Use the shift calculator inside HourMath: enter a start time and an end time in 24-hour format, tick the overnight option if the shift crosses midnight, subtract any break minutes, and add the net duration straight into your list of entries with one click.</p></div>\n      <div class=\"border border-[#FDBA74] rounded-2xl p-5\"><h3 class=\"font-bold\">How do I copy my hours into a timesheet or spreadsheet?</h3><p class=\"mt-2 leading-relaxed text-[#7C2D12]\">HourMath builds tab-separated timesheet rows with a label, sign, HH:MM value, and decimal value for every entry, plus a total row. Press Copy Timesheet and paste directly into Excel, Google Sheets, or your payroll system \u2014 each value lands in its own column. You can also download the rows as a text or CSV file.</p></div>\n    </div>\n  </article>\n</main>\n\n<div class=\"no-print mx-auto max-w-6xl px-4 sm:px-6 pb-4\" role=\"complementary\" aria-label=\"Advertisement\">\n  <div class=\"mx-auto text-center\" style=\"max-width:728px\">\n    <span class=\"block text-[10px] tracking-[0.18em] uppercase text-slate-400 mb-1.5\">Advertisement</span>\n    <div class=\"flex justify-center overflow-hidden\">\n      <script async src=\"https://js.wpadmngr.com/static/adManager.js\" data-admpid=\"464498\"></script>\n    </div>\n  </div>\n</div>\n\n<footer class=\"border-t-2 border-[#9A3412] py-8 text-center text-sm text-[#7C2D12]\">\n  <p class=\"font-display font-bold text-lg text-[#431407]\">HourMath \u2014 Time Duration Calculator</p>\n  <p class=\"mt-1\">Add it up honestly. Every minute counts, and now every minute is counted.</p>\n<p class=\"fx-credit\" style=\"text-align:center;font-size:12.5px;opacity:.62;margin:10px auto 2px;letter-spacing:.01em\">Made by <a href=\"https://fixoraa.tech\" target=\"_blank\" rel=\"noopener\" style=\"color:inherit;font-weight:700;text-decoration:underline;text-underline-offset:2px\">Fixoraa</a></p>\n</footer>\n\n<script id=\"lib-hourmath\">\nvar HourMathLib = (function () {\n  'use strict';\n\n  function isFiniteNum(n) { return typeof n === 'number' && isFinite(n); }\n\n  // Parse a duration string into total minutes (float, seconds preserved as fractions).\n  // Accepts: \"2:30\", \"2:30:15\", \"1.5\" (decimal hours), \"90\" with unit via fallback,\n  // \"2h 30m\", \"2h\", \"45m\", \"45 min\", \"-1:15\", \"+0:45\".\n  // Returns null when invalid or empty.\n  function parseTimeToMinutes(str) {\n    if (typeof str !== 'string') return null;\n    var s = str.trim();\n    if (!s) return null;\n    var sign = 1;\n    if (s.charAt(0) === '-') { sign = -1; s = s.slice(1).trim(); }\n    else if (s.charAt(0) === '+') { s = s.slice(1).trim(); }\n    if (!s) return null;\n\n    // Colon format HH:MM or HH:MM:SS\n    if (s.indexOf(':') !== -1) {\n      var parts = s.split(':');\n      if (parts.length !== 2 && parts.length !== 3) return null;\n      for (var i = 0; i < parts.length; i++) {\n        if (!/^\\d+$/.test(parts[i].trim())) return null;\n      }\n      var h = parseInt(parts[0], 10);\n      var m = parseInt(parts[1], 10);\n      var sec = parts.length === 3 ? parseInt(parts[2], 10) : 0;\n      if (m > 59 || sec > 59) return null;\n      if (h > 9999) return null;\n      return sign * (h * 60 + m + sec / 60);\n    }\n\n    // Unit format: \"2h 30m\", \"2h\", \"45m\", \"1h 15m 30s\"\n    var unitMatch = s.match(/^(?:(\\d+(?:\\.\\d+)?)\\s*h(?:ours?)?)?\\s*(?:(\\d+(?:\\.\\d+)?)\\s*m(?:in(?:utes?)?)?)?\\s*(?:(\\d+(?:\\.\\d+)?)\\s*s(?:ec(?:onds?)?)?)?$/i);\n    if (unitMatch && (unitMatch[1] !== undefined || unitMatch[2] !== undefined || unitMatch[3] !== undefined) && /[hms]/i.test(s)) {\n      var uh = unitMatch[1] ? parseFloat(unitMatch[1]) : 0;\n      var um = unitMatch[2] ? parseFloat(unitMatch[2]) : 0;\n      var us = unitMatch[3] ? parseFloat(unitMatch[3]) : 0;\n      return sign * (uh * 60 + um + us / 60);\n    }\n\n    // Plain number = decimal hours, e.g. \"1.5\" or \"2\"\n    if (/^\\d+(?:\\.\\d+)?$/.test(s)) {\n      return sign * parseFloat(s) * 60;\n    }\n    return null;\n  }\n\n  function isValidDuration(str) { return parseTimeToMinutes(str) !== null; }\n\n  // Format total minutes as HH:MM (hours may exceed 24). Rounds to nearest minute.\n  function formatHHMM(totalMinutes) {\n    if (!isFiniteNum(totalMinutes)) return '';\n    var rounded = Math.round(totalMinutes);\n    var neg = rounded < 0;\n    var abs = Math.abs(rounded);\n    var h = Math.floor(abs / 60);\n    var m = abs % 60;\n    return (neg ? '-' : '') + h + ':' + (m < 10 ? '0' : '') + m;\n  }\n\n  // Format as H:MM:SS\n  function formatHHMMSS(totalMinutes) {\n    if (!isFiniteNum(totalMinutes)) return '';\n    var totalSec = Math.round(totalMinutes * 60);\n    var neg = totalSec < 0;\n    var abs = Math.abs(totalSec);\n    var h = Math.floor(abs / 3600);\n    var m = Math.floor((abs % 3600) / 60);\n    var sec = abs % 60;\n    function p(n) { return (n < 10 ? '0' : '') + n; }\n    return (neg ? '-' : '') + h + ':' + p(m) + ':' + p(sec);\n  }\n\n  // Decimal hours string, e.g. 150 min -> \"2.50\"\n  function formatDecimal(totalMinutes, decimals) {\n    if (!isFiniteNum(totalMinutes)) return '';\n    var d = (typeof decimals === 'number') ? decimals : 2;\n    return (totalMinutes / 60).toFixed(d);\n  }\n\n  // Sum rows: [{ minutes:number, op:'+'|'-' }] or [{ text, op }] -> total minutes or null if any invalid\n  function sumEntries(entries) {\n    if (!Array.isArray(entries)) return null;\n    var total = 0;\n    for (var i = 0; i < entries.length; i++) {\n      var e = entries[i];\n      if (!e) return null;\n      var mins;\n      if (typeof e.minutes === 'number') mins = e.minutes;\n      else if (typeof e.text === 'string') { mins = parseTimeToMinutes(e.text); if (mins === null) return null; }\n      else if (typeof e.value === 'string') { mins = parseTimeToMinutes(e.value); if (mins === null) return null; }\n      else return null;\n      var op = (e.op === '-' || e.sign === -1) ? -1 : 1;\n      total += op * mins;\n    }\n    return total;\n  }\n\n  // Difference between two clock times \"HH:MM\" (24h) -> minutes, handling overnight when end<start\n  function clockDiffMinutes(startStr, endStr, overnight) {\n    function parseClock(s) {\n      if (typeof s !== 'string') return null;\n      var m = /^\\s*(\\d{1,2}):(\\d{2})\\s*$/.exec(s);\n      if (!m) return null;\n      var h = parseInt(m[1], 10), mi = parseInt(m[2], 10);\n      if (h > 23 || mi > 59) return null;\n      return h * 60 + mi;\n    }\n    var a = parseClock(startStr), b = parseClock(endStr);\n    if (a === null || b === null) return null;\n    var diff = b - a;\n    if (diff < 0 && overnight) diff += 1440;\n    return diff;\n  }\n\n  // Payroll rounding: round total minutes to nearest increment (6, 10, 15, 30)\n  // mode: 'nearest' | 'up' | 'down'\n  function roundForPayroll(totalMinutes, increment, mode) {\n    if (!isFiniteNum(totalMinutes)) return null;\n    var inc = (typeof increment === 'number' && increment > 0) ? increment : 15;\n    var md = mode || 'nearest';\n    if (md === 'up') return Math.ceil(totalMinutes / inc) * inc;\n    if (md === 'down') return Math.floor(totalMinutes / inc) * inc;\n    return Math.round(totalMinutes / inc) * inc;\n  }\n\n  // Split total minutes into days/hours/minutes components\n  function splitDuration(totalMinutes) {\n    if (!isFiniteNum(totalMinutes)) return null;\n    var rounded = Math.round(totalMinutes);\n    var neg = rounded < 0;\n    var abs = Math.abs(rounded);\n    return {\n      negative: neg,\n      days: Math.floor(abs / 1440),\n      hours: Math.floor((abs % 1440) / 60),\n      minutes: abs % 60,\n      totalMinutes: rounded,\n      totalHoursDecimal: abs / 60\n    };\n  }\n\n  // Build a copyable timesheet line: \"Label\\tHH:MM\\tDecimal\"\n  function buildTimesheetRow(label, totalMinutes) {\n    if (!isFiniteNum(totalMinutes)) return '';\n    var lab = (typeof label === 'string' && label.trim()) ? label.trim() : 'Total';\n    return lab + '\\t' + formatHHMM(totalMinutes) + '\\t' + formatDecimal(totalMinutes, 2);\n  }\n\n  // Build full timesheet text from rows [{label, minutes/op}] plus total\n  function buildTimesheet(rows, totalMinutes) {\n    if (!Array.isArray(rows)) return '';\n    var lines = [];\n    for (var i = 0; i < rows.length; i++) {\n      var r = rows[i];\n      var mins = (typeof r.minutes === 'number') ? r.minutes : parseTimeToMinutes(r.text || r.value || '');\n      if (mins === null) continue;\n      var op = (r.op === '-') ? '-' : '+';\n      var lab = r.label || ('Entry ' + (i + 1));\n      lines.push(lab + '\\t' + op + '\\t' + formatHHMM(mins) + '\\t' + formatDecimal(mins, 2));\n    }\n    if (isFiniteNum(totalMinutes)) {\n      lines.push('TOTAL\\t\\t' + formatHHMM(totalMinutes) + '\\t' + formatDecimal(totalMinutes, 2));\n    }\n    return lines.join('\\n');\n  }\n\n  // Average duration across entries total/count\n  function averageMinutes(totalMinutes, count) {\n    if (!isFiniteNum(totalMinutes) || typeof count !== 'number' || count <= 0) return null;\n    return totalMinutes / count;\n  }\n\n  // Multiply a duration by a factor (e.g. hourly rate billing: minutes * rate = money)\n  function billableAmount(totalMinutes, hourlyRate) {\n    if (!isFiniteNum(totalMinutes) || !isFiniteNum(hourlyRate)) return null;\n    return (totalMinutes / 60) * hourlyRate;\n  }\n\n  return {\n    parseTimeToMinutes: parseTimeToMinutes,\n    isValidDuration: isValidDuration,\n    formatHHMM: formatHHMM,\n    formatHHMMSS: formatHHMMSS,\n    formatDecimal: formatDecimal,\n    sumEntries: sumEntries,\n    clockDiffMinutes: clockDiffMinutes,\n    roundForPayroll: roundForPayroll,\n    splitDuration: splitDuration,\n    buildTimesheetRow: buildTimesheetRow,\n    buildTimesheet: buildTimesheet,\n    averageMinutes: averageMinutes,\n    billableAmount: billableAmount\n  };\n})();\n\nif (typeof module !== 'undefined' && module.exports) { module.exports = HourMathLib; }\n\n</script>\n<script>\n(function(){\n  var L = HourMathLib;\n  var entries = []; // {id,label,text,op}\n  var nextId = 1;\n  var lastShiftMinutes = null;\n  var els = {\n    list: document.getElementById('entriesList'), empty: document.getElementById('emptyState'),\n    total: document.getElementById('displayTotal'), sub: document.getElementById('displaySub'),\n    brk: document.getElementById('displayBreak'), avg: document.getElementById('displayAvg'),\n    msg: document.getElementById('calcMsg'), count: document.getElementById('entryCount'),\n    sheet: document.getElementById('timesheetOut'), rounded: document.getElementById('roundedOut'),\n    billable: document.getElementById('billableOut'), copyMsg: document.getElementById('copyMsg')\n  };\n  function minsOf(e){ return L.parseTimeToMinutes(e.text); }\n  function currentTotal(){\n    var t = 0, valid = true;\n    entries.forEach(function(e){ var m = minsOf(e); if(m===null){ valid=false; return; } t += (e.op==='-'?-1:1)*m; });\n    return valid ? t : null;\n  }\n  function render(){\n    els.list.innerHTML = '';\n    entries.forEach(function(e){\n      var m = minsOf(e);\n      var row = document.createElement('div');\n      row.className = 'flex flex-wrap sm:flex-nowrap items-center gap-2 bg-white border ' + (m===null ? 'border-red-400' : 'border-[#FDBA74]') + ' rounded-2xl p-2.5';\n      row.innerHTML =\n        '<button data-act=\"toggle\" class=\"w-10 h-11 shrink-0 rounded-xl font-mono2 font-bold text-lg ' + (e.op==='-' ? 'bg-red-100 text-red-800' : 'bg-green-100 text-green-800') + '\">' + (e.op==='-' ? '\u2212' : '+') + '</button>' +\n        '<input data-f=\"label\" value=\"\" class=\"flex-1 min-w-[110px] rounded-xl border border-[#E7E5E4] px-3 py-2.5 text-sm font-semibold\" placeholder=\"Label, e.g. Monday shift\">' +\n        '<input data-f=\"text\" value=\"\" class=\"w-28 rounded-xl border border-[#E7E5E4] px-3 py-2.5 font-mono2 font-bold text-center\" placeholder=\"7:30\">' +\n        '<span data-f=\"dec\" class=\"w-20 text-right font-mono2 text-xs text-[#9A3412] font-bold\">' + (m===null ? 'invalid' : L.formatDecimal(m,2)+' hrs') + '</span>' +\n        '<button data-act=\"del\" class=\"w-10 h-11 shrink-0 rounded-xl bg-[#FFF7ED] border border-[#FDBA74] font-bold\" aria-label=\"Delete entry\">\u00d7</button>';\n      row.querySelector('[data-f=\"label\"]').value = e.label;\n      row.querySelector('[data-f=\"text\"]').value = e.text;\n      row.querySelector('[data-f=\"label\"]').addEventListener('input', function(ev){ e.label = ev.target.value; renderSheetOnly(); });\n      row.querySelector('[data-f=\"text\"]').addEventListener('input', function(ev){ e.text = ev.target.value; var mm = minsOf(e); row.querySelector('[data-f=\"dec\"]').textContent = (mm===null ? 'invalid' : L.formatDecimal(mm,2)+' hrs'); row.style.borderColor = (mm===null ? '#F87171' : '#FDBA74'); updateTotals(); renderSheetOnly(); });\n      row.querySelector('[data-act=\"toggle\"]').addEventListener('click', function(){ e.op = (e.op==='-') ? '+' : '-'; render(); });\n      row.querySelector('[data-act=\"del\"]').addEventListener('click', function(){ entries = entries.filter(function(x){ return x.id!==e.id; }); render(); });\n      els.list.appendChild(row);\n    });\n    els.empty.style.display = entries.length ? 'none' : 'block';\n    els.count.textContent = entries.length ? '('+entries.length+' row'+(entries.length>1?'s':'')+')' : '';\n    updateTotals(); renderSheetOnly();\n  }\n  function renderSheetOnly(){\n    var total = currentTotal();\n    var rows = entries.map(function(e){ return { label: e.label, text: e.text, op: e.op, minutes: minsOf(e) }; });\n    els.sheet.value = total===null ? '' : L.buildTimesheet(rows, total);\n  }\n  function updateTotals(){\n    var total = currentTotal();\n    if(entries.length===0){\n      els.total.textContent='0:00'; els.sub.textContent='0.00 decimal hours \u00b7 0 minutes';\n      els.brk.textContent='0 days \u00b7 0 hrs \u00b7 0 min'; els.avg.textContent='Average per entry: \u2014';\n      els.msg.textContent='Add your first duration below \u2014 try 7:30, 1.5, or 45m. All three formats work.';\n    } else if(total===null){\n      els.total.textContent='\u2014'; els.sub.textContent='Fix the highlighted entry to see the total.';\n      els.msg.textContent='\u26a0 One entry could not be read. Use formats like 7:30, 1.5, 2h 30m, or 45m \u2014 minutes after a colon must be 00\u201359.';\n    } else {\n      els.total.textContent = L.formatHHMM(total);\n      els.sub.textContent = L.formatDecimal(total,2)+' decimal hours \u00b7 '+Math.round(total)+' minutes \u00b7 '+L.formatHHMMSS(total)+' with seconds';\n      var s = L.splitDuration(total);\n      els.brk.textContent = (s.negative?'\u2212':'')+s.days+' days \u00b7 '+s.hours+' hrs \u00b7 '+s.minutes+' min';\n      var avg = L.averageMinutes(total, entries.length);\n      els.avg.textContent = 'Average per entry: '+L.formatHHMM(avg)+' ('+L.formatDecimal(avg,2)+' hrs)';\n      els.msg.textContent = '\u2713 Total updated. Copy the timesheet rows on the pad when you are ready.';\n    }\n    // payroll\n    var inc = parseInt(document.getElementById('roundInc').value,10);\n    var mode = document.getElementById('roundMode').value;\n    var rate = parseFloat(document.getElementById('hourlyRate').value);\n    if(total===null){ els.rounded.textContent='\u2014'; els.billable.textContent='\u2014'; }\n    else {\n      var rt = inc>0 ? L.roundForPayroll(total, inc, mode) : total;\n      els.rounded.textContent = L.formatHHMM(rt)+' \u00b7 '+L.formatDecimal(rt,2)+' hrs';\n      els.billable.textContent = isFinite(rate) && rate>=0 ? L.billableAmount(rt, rate).toFixed(2) : '\u2014';\n    }\n  }\n  function addEntry(label, text, op){\n    entries.push({ id: nextId++, label: label||'', text: text||'', op: op||'+' });\n    render();\n  }\n  document.getElementById('addEntryBtn').addEventListener('click', function(){ addEntry('', '', '+'); var inputs = els.list.querySelectorAll('[data-f=\"text\"]'); if(inputs.length) inputs[inputs.length-1].focus(); });\n  document.getElementById('clearBtn').addEventListener('click', function(){ entries=[]; render(); });\n  document.querySelectorAll('.quick-add').forEach(function(b){ b.addEventListener('click', function(){ var m=parseInt(b.getAttribute('data-mins'),10); addEntry('Quick add', L.formatHHMM(m), '+'); }); });\n  document.querySelectorAll('.quick-sub').forEach(function(b){ b.addEventListener('click', function(){ addEntry('Break', '0:30', '-'); }); });\n  document.querySelectorAll('[data-preset]').forEach(function(b){ b.addEventListener('click', function(){\n    if(b.getAttribute('data-preset')==='workday') addEntry('Workday','8:00','+');\n    else { entries=[]; [['Monday','7:30'],['Tuesday','8:15'],['Wednesday','7:45'],['Thursday','8:00'],['Friday','6:30']].forEach(function(d){ entries.push({id:nextId++,label:d[0],text:d[1],op:'+'}); }); entries.push({id:nextId++,label:'Long lunch (Fri)',text:'0:30',op:'-'}); render(); }\n  }); });\n  ['roundInc','roundMode','hourlyRate'].forEach(function(id){ document.getElementById(id).addEventListener('input', updateTotals); document.getElementById(id).addEventListener('change', updateTotals); });\n  document.getElementById('shiftCalcBtn').addEventListener('click', function(){\n    var s=document.getElementById('shiftStart').value, e=document.getElementById('shiftEnd').value;\n    var brk=parseFloat(document.getElementById('shiftBreak').value)||0;\n    var ov=document.getElementById('shiftOvernight').checked;\n    var diff=L.clockDiffMinutes(s,e,ov);\n    var out=document.getElementById('shiftResult'), addBtn=document.getElementById('shiftAddBtn');\n    if(diff===null){ out.textContent='Enter valid start and end times.'; addBtn.classList.add('hidden'); lastShiftMinutes=null; return; }\n    lastShiftMinutes = diff - brk;\n    out.textContent = 'Gross '+L.formatHHMM(diff)+' \u2212 break '+brk+'m = net '+L.formatHHMM(lastShiftMinutes)+' ('+L.formatDecimal(lastShiftMinutes,2)+' hrs)';\n    addBtn.classList.remove('hidden');\n  });\n  document.getElementById('shiftAddBtn').addEventListener('click', function(){ if(lastShiftMinutes===null) return; addEntry('Shift', L.formatHHMM(lastShiftMinutes), lastShiftMinutes<0?'-':'+'); if(lastShiftMinutes<0){ entries[entries.length-1].text=L.formatHHMM(Math.abs(lastShiftMinutes)); } });\n  document.getElementById('copyBtn').addEventListener('click', function(){\n    if(!els.sheet.value){ els.copyMsg.textContent='Add at least one valid entry first.'; return; }\n    function done(){ els.copyMsg.textContent='\u2713 Timesheet copied \u2014 paste it straight into your spreadsheet.'; }\n    if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(els.sheet.value).then(done).catch(function(){ els.sheet.select(); document.execCommand('copy'); done(); }); }\n    else { els.sheet.select(); document.execCommand('copy'); done(); }\n  });\n  document.getElementById('csvBtn').addEventListener('click', function(){\n    if(!els.sheet.value){ els.copyMsg.textContent='Add at least one valid entry first.'; return; }\n    var csv = els.sheet.value.split('\\n').map(function(line){ return line.split('\\t').map(function(c){ return '\"'+String(c).replace(/\"/g,'\"\"')+'\"'; }).join(','); }).join('\\n');\n    var a=document.createElement('a'); a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'})); a.download='hourmath-timesheet.csv'; a.click(); URL.revokeObjectURL(a.href);\n    els.copyMsg.textContent='\u2713 CSV downloaded.';\n  });\n  // Seed with two helpful rows\n  addEntry('Example \u2014 Monday', '7:30', '+');\n  addEntry('Example \u2014 Tuesday', '8:15', '+');\n})();\n</script>\n</body>\n</html>\n"};
export default {
  async fetch(request, env, ctx) {
    const url = new URL(request.url);
    const page = GUESTS[url.hostname];
    if (page !== undefined) {
      if (url.pathname !== "/" && url.pathname !== "/index.html") {
        return new Response("Not found", { status: 404 });
      }
      return new Response(page, { headers: { "content-type": "text/html;charset=UTF-8" } });
    }
    return original.fetch(request, env, ctx);
  }
};